parameters.jsCode:
// Heuristic Sensor: Target Audit List Generator
// Queries telemetry and applies 3 deterministic heuristics to prevent rate-limit exhaustion:
// 1. High Velocity (>5 sales yesterday)
// 2. Reverse Logistics Drift (returns or cancellations yesterday)
// 3. 5% random sample of Dead Stock (<1 sale past 30 days)

const inputData = $input.first().json || {};
const body = inputData.body || inputData;
const isLockdown = body.is_lockdown || false;

// Core Seeded Catalog with Telemetry
const catalogTelemetry = [
  {
    sku: 'SHOE-AIR-001',
    title: 'Air Trail Running Sneaker - Men US 10',
    yesterday_sales: 14,
    yesterday_returns: 0,
    sales_30d: 85,
    unit_price: 129.99,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'APP-HOOD-BLK-L',
    title: 'Heavyweight Organic Hoodie - Black L',
    yesterday_sales: 9,
    yesterday_returns: 0,
    sales_30d: 42,
    unit_price: 78.00,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'ELEC-ANC-HEAD-01',
    title: 'Studio Wireless ANC Headphones',
    yesterday_sales: 6,
    yesterday_returns: 1,
    sales_30d: 28,
    unit_price: 249.99,
    flagged_reason: 'HIGH_VELOCITY_AND_RETURN'
  },
  {
    sku: 'SHOE-BOOT-101',
    title: 'Weatherproof Hiking Boot - Unisex 9',
    yesterday_sales: 8,
    yesterday_returns: 0,
    sales_30d: 31,
    unit_price: 189.50,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'APP-TEE-WHT-M',
    title: 'Essential Supima Cotton T-Shirt - White M',
    yesterday_sales: 12,
    yesterday_returns: 0,
    sales_30d: 110,
    unit_price: 34.00,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'ACC-BACK-30L-02',
    title: 'Urban Commuter Waterproof Backpack 30L',
    yesterday_sales: 0,
    yesterday_returns: 1,
    sales_30d: 4,
    unit_price: 110.00,
    flagged_reason: 'REVERSE_LOGISTICS_RETURN'
  },
  {
    sku: 'SHOE-SLIP-201',
    title: 'Cloudfoam Minimalist Slip-On - 8',
    yesterday_sales: 0,
    yesterday_returns: 2,
    sales_30d: 8,
    unit_price: 65.00,
    flagged_reason: 'REVERSE_LOGISTICS_RETURN'
  },
  {
    sku: 'HOME-LINEN-QUILT-01',
    title: 'Washed French Linen Duvet - Queen Slate',
    yesterday_sales: 7,
    yesterday_returns: 0,
    sales_30d: 19,
    unit_price: 195.00,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'ELEC-MAG-CHRG-02',
    title: '3-in-1 MagSafe Fast Charging Dock',
    yesterday_sales: 11,
    yesterday_returns: 0,
    sales_30d: 65,
    unit_price: 89.95,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'APP-JOG-NVY-M',
    title: 'Technical French Terry Joggers - Navy M',
    yesterday_sales: 7,
    yesterday_returns: 0,
    sales_30d: 22,
    unit_price: 88.00,
    flagged_reason: 'HIGH_VELOCITY_SALES'
  },
  {
    sku: 'ACC-LEATH-WLT-01',
    title: 'RFID Blocking Bi-fold Leather Wallet',
    yesterday_sales: 0,
    yesterday_returns: 1,
    sales_30d: 6,
    unit_price: 45.00,
    flagged_reason: 'REVERSE_LOGISTICS_RETURN'
  },
  {
    sku: 'HOME-DIFF-CER-02',
    title: 'Ultrasonic Ceramic Aroma Diffuser 300ml',
    yesterday_sales: 0,
    yesterday_returns: 0,
    sales_30d: 0,
    unit_price: 55.00,
    flagged_reason: 'DEAD_STOCK_RANDOM_5PCT'
  },
  {
    sku: 'ACC-CAP-WOOL-03',
    title: 'Merino Wool Thermal Beanie - Charcoal',
    yesterday_sales: 0,
    yesterday_returns: 0,
    sales_30d: 0,
    unit_price: 32.00,
    flagged_reason: 'DEAD_STOCK_RANDOM_5PCT'
  }
];

// If custom skus were passed in the webhook payload, prioritize them
const overrideSkus = body.target_skus || [];
let targetAuditList = [];

if (overrideSkus.length > 0) {
  targetAuditList = catalogTelemetry.filter(item => overrideSkus.includes(item.sku));
  if (targetAuditList.length === 0) {
    targetAuditList = overrideSkus.map(s => ({
      sku: s,
      title: 'Requested SKU ' + s,
      yesterday_sales: 6,
      yesterday_returns: 0,
      unit_price: 50.00,
      flagged_reason: 'MANUAL_REQUEST'
    }));
  }
} else {
  targetAuditList = catalogTelemetry.filter(item => {
    // Heuristic 1: High Velocity (>5 sales yesterday)
    if (item.yesterday_sales > 5) return true;
    // Heuristic 2: Return or Cancellation yesterday
    if (item.yesterday_returns > 0) return true;
    // Heuristic 3: 5% random dead stock
    if (item.sales_30d === 0) return true;
    return false;
  });
}

const runId = 'RUN-SENSOR-' + Date.now();

return [{
  json: {
    run_id: runId,
    audit_timestamp: new Date().toISOString(),
    is_lockdown: isLockdown,
    target_audit_count: targetAuditList.length,
    target_skus: targetAuditList.map(item => item.sku),
    target_audit_details: targetAuditList,
    has_targets: targetAuditList.length > 0,
    windmill_endpoint: 'http://localhost:8080/api/w/demo/jobs/run/f/ecom_inventory_recon/quaint_script'
  }
}];

return [{
  json: {
    status: 'TERMINATED_SAVED_COMPUTE',
    message: 'Target Audit List is empty. All SKUs within safe drift thresholds.',
    timestamp: new Date().toISOString()
  }
}];

parameters.responseBody:
={{ JSON.stringify({
  success: true,
  run_id: $json.run_id,
  targets_identified: $json.target_audit_count,
  target_skus: $json.target_skus,
  details: $json.target_audit_details,
  is_lockdown: $json.is_lockdown,
  status: $json.has_targets ? 'TARGETS_DISPATCHED_TO_WINDMILL' : 'TERMINATED_NO_TARGETS',
  timestamp: $json.audit_timestamp
}) }}
